// Recebiveis vencendo (ou atrasados): 8h locais do dono, re-aviso a cada 3 dias.
// Webhook manual aceita {force: '<numero>'} pra teste (ignora hora e NAO marca).
let force = '';
try { const b = items[0].json.body || items[0].json; force = String(b.force || '').replace(/[^0-9]/g, ''); } catch (e) {}
const cols = `r.id, r.dono_numero, r.cliente_nome, r.cliente_numero, r.descricao, r.valor, r.moeda,
       to_char(r.vencimento, 'DD/MM') AS venc,
       (r.vencimento < (NOW() AT TIME ZONE d.timezone)::date) AS atrasado,
       d.nome AS dono_nome, d.idioma, d.pix_chave`;
let sql;
if (force) {
  sql = `SELECT ${cols} FROM giulia_recebiveis r JOIN giulia_donos d ON d.numero = r.dono_numero
WHERE r.dono_numero = '${force}' AND r.status = 'pendente' AND r.vencimento <= (NOW() AT TIME ZONE d.timezone)::date
ORDER BY r.vencimento ASC LIMIT 5;`;
} else {
  sql = `WITH alvo AS (
  SELECT r.id FROM giulia_recebiveis r
  JOIN giulia_donos d ON d.numero = r.dono_numero
  WHERE r.status = 'pendente'
    AND COALESCE(d.status, 'ativo') = 'ativo'
    AND (d.numero = '5511910441709' OR EXISTS (SELECT 1 FROM giulia_memoria m WHERE m.from_numero = d.numero AND m.role = 'user' AND m.created_at > NOW() - INTERVAL '5 days'))
    AND r.vencimento <= (NOW() AT TIME ZONE d.timezone)::date
    AND to_char(NOW() AT TIME ZONE d.timezone, 'HH24')::int = 8
    AND (r.ultimo_aviso IS NULL OR r.ultimo_aviso < NOW() - INTERVAL '3 days')
  FOR UPDATE OF r SKIP LOCKED
  LIMIT 20
), upd AS (
  UPDATE giulia_recebiveis r2 SET ultimo_aviso = NOW() FROM alvo WHERE r2.id = alvo.id
  RETURNING r2.id, r2.dono_numero, r2.cliente_nome, r2.cliente_numero, r2.descricao, r2.valor, r2.moeda, r2.vencimento
)
SELECT u.id, u.dono_numero, u.cliente_nome, u.cliente_numero, u.descricao, u.valor, u.moeda,
       to_char(u.vencimento, 'DD/MM') AS venc,
       (u.vencimento < (NOW() AT TIME ZONE d.timezone)::date) AS atrasado,
       d.nome AS dono_nome, d.idioma, d.pix_chave
FROM upd u JOIN giulia_donos d ON d.numero = u.dono_numero;`;
}
return [{ json: { sql, force: force || null } }];

// Um aviso por recebivel: resumo pro dono + mensagem de cobranca PRONTA pra encaminhar
const out = [];
const esc = s => String(s == null ? '' : s).replace(/'/g, "''");
for (const it of items) {
  const r = it.json;
  if (!r || !r.id) continue;
  const mSym = r.moeda === 'USD' ? '$' : 'R$';
  const val = mSym + ' ' + Number(r.valor).toFixed(2).replace('.', ',').replace(/\B(?=(\d{3})+(?!\d))/g, '.');
  // pula titulo honorifico (Sr/Sra/Dr/Mr...) pro 'Oi Fulano' sair natural
  const partesNome = String(r.cliente_nome).trim().split(/\s+/);
  const honorifico = /^(sr|sra|srta|dr|dra|dona|seu|mr|mrs|ms|dr)\.?$/i;
  const primeiroNome = (honorifico.test(partesNome[0]) && partesNome.length > 1)
    ? partesNome.slice(0, 2).join(' ')
    : partesNome[0];
  const situacao = r.atrasado ? `venceu dia ${r.venc} e ainda nao caiu` : `vence HOJE (${r.venc})`;
  const pixLinha = r.pix_chave ? ` Pode fazer no Pix: ${r.pix_chave}.` : '';
  const cobranca = `Oi ${primeiroNome}, tudo bem? Passando pra lembrar do pagamento de ${val}${r.descricao ? ' (' + r.descricao + ')' : ''} que ${r.atrasado ? 'venceu dia ' + r.venc : 'vence hoje'}.${pixLinha} Qualquer coisa me chama!`;
  const texto = `Cobranca do dia: ${val} do ${r.cliente_nome} ${situacao}.` +
    `\n\nMensagem pronta - e so encaminhar pra ele:` +
    `\n----------` +
    `\n${cobranca}` +
    `\n----------` +
    `\nQuando cair me avisa ('caiu o pix do ${primeiroNome}') que eu marco recebido.` +
    (r.pix_chave ? '' : `\nDica: me fala 'minha chave pix e ...' que eu ja incluo o Pix nas proximas cobrancas.`);
  out.push({ json: {
    number: r.dono_numero,
    texto,
    memoria_sql: "INSERT INTO giulia_memoria (role, content, from_numero) VALUES ('assistant', '" + esc(texto) + "', '" + esc(r.dono_numero) + "');"
  } });
}
return out;
